   129	/// Pin the process start. Called first thing in `main`, before argv handling
   130	/// or config load, so `startup_ms` covers everything that runs before the
   131	/// wrapper's first cache decision. A second call changes nothing.
   132	///
   133	/// Process-wide and permanent: in a test binary, once any test pins it,
   134	/// every later in-process wrapper run measures `elapsed_ms` from that pin.
   135	/// Tests must not assert an upper bound on `elapsed_ms` or `startup_ms`.
   136	pub fn mark_process_start() {
   137	    let _ = PROCESS_START.set(Instant::now());
   138	}
   139	
   140	/// The instant `main` pinned, or `None` when this process never went through
   141	/// `main` (unit tests, library callers). The wrapper then anchors elapsed
   142	/// time at its own entry and records no startup.
   143	pub fn process_start() -> Option<Instant> {
   144	    PROCESS_START.get().copied()
   145	}
